    const promise = (async function () {
      let finalAction: ReturnType<typeof fulfilled | typeof rejected>
      try {
        let conditionResult = options?.condition?.(arg, { getState, extra })
        if (isThenable(conditionResult)) {
          conditionResult = await conditionResult
        }

        if (conditionResult === false) {
          // eslint-disable-next-line no-throw-literal
          throw {
            name: 'ConditionError',
            message: 'Aborted due to condition callback returning false.',
          }
        }
        if (abortController.signal.aborted) {
          // The request was aborted (e.g. via an already-aborted external
          // signal, or `abort()` called during an async `condition`) before
          // the `pending` action was dispatched. Treat this as an abort
          // rather than a condition rejection, so the reason is preserved
          // and the `rejected` action is not silently swallowed.
          // eslint-disable-next-line no-throw-literal
          throw {
            name: 'AbortError',
            message: abortReason || 'Aborted',
          }
        }

        const abortedPromise = new Promise<never>((_, reject) => {
          abortHandler = () => {
            reject({
              name: 'AbortError',
              message: abortReason || 'Aborted',
            })
          }
          abortController.signal.addEventListener('abort', abortHandler, {
            once: true,
          })
        })
        dispatch(
          pending(
            requestId,
            arg,
            options?.getPendingMeta?.(
              { requestId, arg },
              { getState, extra },
            ),
          ) as any,
        )
        finalAction = await Promise.race([
          abortedPromise,
          Promise.resolve(
            payloadCreator(arg, {
              dispatch,
              getState,
              extra,
              requestId,
              signal: abortController.signal,
              abort,
              rejectWithValue: ((
                value: RejectedValue,
                meta?: RejectedMeta,
              ) => {
                return new RejectWithValue(value, meta)
              }) as any,
              fulfillWithValue: ((value: unknown, meta?: FulfilledMeta) => {
                return new FulfillWithMeta(value, meta)
              }) as any,
            }),
          ).then((result) => {
            if (result instanceof RejectWithValue) {
              throw result
            }
            if (result instanceof FulfillWithMeta) {
              return fulfilled(result.payload, requestId, arg, result.meta)
            }
            return fulfilled(result as any, requestId, arg)
          }),
        ])
      } catch (err) {
        finalAction =
          err instanceof RejectWithValue
            ? rejected(null, requestId, arg, err.payload, err.meta)
            : rejected(err as any, requestId, arg)
      } finally {
        if (abortHandler) {
          abortController.signal.removeEventListener('abort', abortHandler)
        }
      }
      // We dispatch the result action _after_ the catch, to avoid having any errors
      // here get swallowed by the try/catch block,
      // per https://twitter.com/dan_abramov/status/770914221638942720
      // and https://github.com/reduxjs/redux-toolkit/blob/e85eb17b39a2118d859f7b7746e0f3fee523e089/docs/tutorials/advanced-tutorial.md#async-error-handling-logic-in-thunks

      const skipDispatch =
        options &&
        !options.dispatchConditionRejection &&
        rejected.match(finalAction) &&
        (finalAction as any).meta.condition

      if (!skipDispatch) {
        dispatch(finalAction as any)
      }
      return finalAction
    })()
    return Object.assign(promise as SafePromise<any>, {
      abort,
      requestId,
      arg,
      unwrap() {
        return promise.then<any>(unwrapResult)
      },
    })
  }
}

function abort(reason?: string) {
  abortReason = reason
  abortController.abort()
}

export const miniSerializeError = (value: any): SerializedError => {
  if (typeof value === 'object' && value !== null) {
    const simpleError: SerializedError = {}
    for (const property of commonProperties) {
      if (typeof value[property] === 'string') {
        simpleError[property] = value[property]
      }
    }

    return simpleError
  }

  return { message: String(value) }
}

export function unwrapResult<R extends UnwrappableAction>(
  action: R,
): UnwrappedActionPayload<R> {
  if (action.meta && action.meta.rejectedWithValue) {
    throw action.payload
  }
  if (action.error) {
    throw action.error
  }
  return action.payload
}

function isThenable(value: any): value is PromiseLike<any> {
  return (
    value !== null &&
    typeof value === 'object' &&
    typeof value.then === 'function'
  )
}

class RejectWithValue<Payload, RejectedMeta> {
  /*
  type-only property to distinguish between RejectWithValue and FulfillWithMeta
  does not exist at runtime
  */
  private readonly _type!: 'RejectWithValue'
  constructor(
    public readonly payload: Payload,
    public readonly meta: RejectedMeta,
  ) {}
}

class FulfillWithMeta<Payload, FulfilledMeta> {
  /*
  type-only property to distinguish between RejectWithValue and FulfillWithMeta
  does not exist at runtime
  */
  private readonly _type!: 'FulfillWithMeta'
  constructor(
    public readonly payload: Payload,
    public readonly meta: FulfilledMeta,
  ) {}
}
